// Works out the porkchop grid (porkchop.js, copied unchanged from commit a4ea6e3) off the page's main thread, on the
// same astronomy-engine states as the page. Generated by portfolio/figures/orrery/build_porkchop.py.
import * as A from "../../vendor/astronomy-engine-2.1.19/astronomy.min.js";
import { porkchopGrid } from "./porkchop.js";
const AU = 149597870.7, AUD = AU / 86400, R = A.Rotation_EQJ_ECL();
const BODY = { venus: A.Body.Venus, earth: A.Body.Earth, mars: A.Body.Mars, jupiter: A.Body.Jupiter };
const stateOf = (k, d) => { const s = A.RotateState(R, A.HelioState(BODY[k], d)); return { r: [s.x * AU, s.y * AU, s.z * AU], v: [s.vx * AUD, s.vy * AUD, s.vz * AUD] }; };
self.onmessage = (e) => {
  const { id, ...o } = e.data;
  const G = porkchopGrid({ stateOf, ...o });
  const out = { nDep: G.nDep, nTof: G.nTof, dvDep: G.dvDep, vinfArr: G.vinfArr, type: G.type };
  self.postMessage({ id, G: out }, [out.dvDep.buffer, out.vinfArr.buffer, out.type.buffer]);
};
